import {tileAt,positionCell} from './definition.mjs';
import {worldGate,worldStageAccess} from './state.mjs';
const moves=[['up',0,-1],['right',1,0],['down',0,1],['left',-1,0]];
export function pathToPoint(w,id,{avoidGrass=true,exact=false}={}){const p=w.definition.points[id],s=w.snapshot(),m=w.map;if(!p||p.mapId!==m.id)throw Error('Target on another map');const start=positionCell(s.position),q=[{...start,path:[]}],seen=new Set([start.x+','+start.y]);for(let i=0;i<q.length;i++){const n=q[i];if(exact?n.x===p.x&&n.y===p.y:Math.abs(n.x-p.x)+Math.abs(n.y-p.y)<=1)return n.path;for(const [dir,dx,dy] of moves){const x=n.x+dx,y=n.y+dy,key=x+','+y;if(seen.has(key)||!w.host.canOccupy(s,m.id,x,y)||avoidGrass&&tileAt(m,x,y).encounter)continue;seen.add(key);q.push({x,y,path:[...n.path,dir]})}}return avoidGrass?pathToPoint(w,id,{avoidGrass:false,exact}):null}
export function mapRoute(w,target){const s=w.snapshot(),q=[{id:w.map.id,warps:[]}],seen=new Set([w.map.id]);for(let i=0;i<q.length;i++){const n=q[i];if(n.id===target)return n.warps;for(const id of w.definition.maps[n.id].warps){const p=w.definition.points[id],m=w.definition.maps[p.targetMapId];if(!m||seen.has(m.id)||!worldStageAccess(s,w.story.contract,m.stageId)||!worldGate(s,w.story.contract,p.gate))continue;seen.add(m.id);q.push({id:m.id,warps:[...n.warps,id]})}}return null}
function cells(m){const q=[m.spawn],seen=new Set([m.spawn.join(',')]);for(let i=0;i<q.length;i++){const[x,y]=q[i];for(const[,dx,dy]of moves){const nx=x+dx,ny=y+dy,key=nx+','+ny;if(seen.has(key)||!tileAt(m,nx,ny).walkable||m.actors.some(a=>a.x===nx&&a.y===ny))continue;seen.add(key);q.push([nx,ny])}}return seen}
export function validateWorldDefinition(d,adapter){const c=adapter.encounterRuntime,story=c.story,errors=[],seen=new Set([d.initialMapId]),q=[d.initialMapId];let count=0;
 for(let i=0;i<q.length;i++)for(const id of d.maps[q[i]].warps){const p=d.points[id];if(!d.maps[p.targetMapId]){errors.push({code:'MISSING_WARP_DESTINATION',id});continue}if(!seen.has(p.targetMapId)){seen.add(p.targetMapId);q.push(p.targetMapId)}}
 for(const m of Object.values(d.maps)){if(!seen.has(m.id))errors.push({code:'ISOLATED_MAP',id:m.id});const reach=cells(m);for(const a of m.actors)if(!tileAt(m,a.x,a.y).walkable)errors.push({code:'ACTOR_COLLISION',id:a.id});
  for(const id of m.points){const p=d.points[id],ok=reach.has(p.x+','+p.y)||moves.some(([,dx,dy])=>reach.has((p.x+dx)+','+(p.y+dy)));if(ok)count++;else errors.push({code:'UNREACHABLE_INTERACTION',id});if(p.kind==='warp'){if(d.points[p.reverseId]?.targetMapId!==m.id)errors.push({code:'NONRETURNING_WARP',id});if(!tileAt(d.maps[p.targetMapId],...p.target).walkable||d.maps[p.targetMapId]?.actors.some(a=>a.x===p.target[0]&&a.y===p.target[1]))errors.push({code:'INVALID_WARP_LANDING',id})}if(p.kind==='fishing'&&(!reach.has(p.x+','+p.y)||!tileAt(m,...p.water).water))errors.push({code:'INVALID_FISHING_POINT',id})}
  for(const z of m.encounterZones){if(z.policyExcluded){if(!c.policyExcludedTables[z.tableId]||z.profile!=='NONE')errors.push({code:'POLICY_A_VIOLATION',id:z.id})}else if(!c.tables[z.tableId]?.active||c.tables[z.tableId].rod)errors.push({code:'INVALID_WALK_TABLE',id:z.id});if(!z.policyExcluded&&!reach.has(z.rect[0]+','+z.rect[1]))errors.push({code:'UNREACHABLE_ENCOUNTER',id:z.id})}
 }
 for(const a of Object.values(c.areas))if(!d.areaBindings[a.id])errors.push({code:'MISSING_AREA',id:a.id});for(const t of Object.values(story.trainers))if(!d.trainerBindings[t.id])errors.push({code:'MISSING_TRAINER',id:t.id});for(const e of Object.values(story.events).filter(e=>e.active))if(!d.eventBindings[e.id])errors.push({code:'MISSING_STORY_EVENT',id:e.id});
 const walk=Object.values(d.maps).flatMap(m=>m.encounterZones.filter(z=>!z.policyExcluded).map(z=>z.tableId)),fish=Object.values(d.fishingBindings).flatMap(id=>d.points[id].tableIds),all=[...walk,...fish];for(const t of Object.values(c.tables))if(!all.includes(t.id))errors.push({code:'UNBOUND_TABLE',id:t.id});if(new Set(all).size!==all.length)errors.push({code:'DUPLICATE_TABLE_BINDING'});
 return {version:d.version,pass:!errors.length,errors,mapCount:Object.keys(d.maps).length,reachableMapCount:seen.size,reachablePointCount:count,stageCount:story.sequence.length,areaCount:Object.keys(d.areaBindings).length,trainerCount:Object.keys(d.trainerBindings).length,genericTrainerCount:Object.values(story.trainers).filter(t=>['route_general','gym_subtrainer'].includes(t.kind)).length,storyEventCount:Object.keys(d.eventBindings).length,walkingTableCount:walk.length,fishingTableCount:fish.length,fishingAreaCount:Object.keys(d.fishingBindings).length,fishingRowCount:fish.reduce((n,id)=>n+c.tables[id].slots.length,0),policyExcludedCount:Object.values(d.maps).flatMap(m=>m.encounterZones).filter(z=>z.policyExcluded).length,mode:'STRUCTURAL_PLUS_SEPARATE_STATEFUL_FIXTURE'};
}
